"""Generate docs/evaluation_report.md and docs/model_card.md from STORED, MEASURED results.  python -m app.report

Nothing in the generated documents is typed by hand: every number is read from the active model run's stored evaluation
and the business-impact benchmark (re-run here if missing). Regenerate after retraining.
"""
from __future__ import annotations

import json
import sys

from app.api.common import clean
from app.core.config import ROOT, get_settings
from app.db import models as m
from app.db.session import session_scope
from app.services.business_impact import run_business_impact

DOCS = ROOT / "docs"
NAMES = {"1_simple_rules": "Simple rules", "2_transaction_only_ml": "Transaction-only ML", "3_behavioral_ml": "Behavioural ML", "4_graph_enhanced_ml": "Graph-enhanced ML",
         "4b_combined_features_ml": "All features ML", "5_aegis_combined_risk": "**AEGIS combined risk prioritisation**", "5b_pattern_only": "Pattern evidence only",
         "5c_model_signal_only": "Model signal only", "5d_rules_pattern_plus_behavior": "Rules (pattern + behaviour, no ML)"}


def f(v, d=3):
    return "—" if v is None else f"{v:.{d}f}"


def pc(v, d=1):
    return "—" if v is None else f"{100 * v:.{d}f}%"


def order_sentence(mm) -> str:
    val = sorted(['A_transaction', 'B_behavioral', 'C_graph', 'D_combined'], key=lambda g: -mm[f'{g}/lightgbm']['validation']['pr_auc'])
    tst = sorted(['A_transaction', 'B_behavioral', 'C_graph', 'D_combined'], key=lambda g: -mm[f'{g}/lightgbm']['test']['pr_auc'])
    same = val == tst
    return (f"Ranking of feature groups by validation PR-AUC: {' > '.join(g[0] for g in val)}; by test PR-AUC: {' > '.join(g[0] for g in tst)} ("
            + ("the orderings agree" if same else "the orderings differ, so the middle ranks are not robust") + "). With ~20–30 simulated suspicious scenarios per period, group-level conclusions carry wide uncertainty.")


def main():
    DOCS.mkdir(exist_ok=True)
    with session_scope() as s:
        run = s.query(m.ModelRun).filter(m.ModelRun.is_active.is_(True)).first()
        if run is None:
            sys.exit("no active model; run `python -m app.cli all` first")
        em = run.evaluation_metrics
        ds = s.get(m.Dataset, run.dataset_id)
        ds_info = {"name": ds.name, "n_tx": ds.n_transactions, "n_acc": ds.n_accounts, "version": ds.dataset_version, "min": ds.min_ts, "max": ds.max_ts, "meta": ds.meta or {}}
        rp = get_settings().artifact_dir / "reports" / "business_impact.json"
        if rp.exists() and json.loads(rp.read_text(encoding="utf-8")).get("model_version") == run.model_version:
            bi = json.loads(rp.read_text(encoding="utf-8"))
        else:
            print("running business-impact benchmark …")
            bi = clean(run_business_impact(s, run.dataset_id))
            rp.parent.mkdir(parents=True, exist_ok=True)
            rp.write_text(json.dumps(bi, indent=1), encoding="utf-8")
        sc = em["split"]
        r = em["results"]
        L = ["# Evaluation report", "", f"> **SYNTHETIC BENCHMARK.** Generated by `python -m app.report` from stored results of model run `{run.model_run_id}` (`{run.model_version}`) on dataset `{run.dataset_id}` (version `{ds_info['version']}`). "
             "Labels describe *simulated* scenarios, not real or legally established financial crime. Absolute numbers will not transfer to real data.", "",
             "## 1. Dataset", f"- {ds_info['n_tx']:,} transactions, {ds_info['n_acc']:,} accounts, {str(ds_info['min'])[:10]} → {str(ds_info['max'])[:10]} (synthetic, seed {ds_info['meta'].get('generator_config', {}).get('seed', '?')}).",
             f"- Positive (simulated-suspicious) transactions — train {sc['positives']['train']:,}, validation {sc['positives']['validation']:,}, test {sc['positives']['test']:,}. Prevalence is far higher than any real portfolio, so **precision values are not transferable**; ranking metrics at fixed capacity are more meaningful.",
             "- Benign look-alike scenarios (payroll, marketplace settlements, group bills, recurring business transfers, seasonal merchants) are labelled *not suspicious*.", "",
             "## 2. Evaluation design", f"- {sc['method']}", f"- Train {sc['train_start'][:10]} → {sc['train_end'][:10]} ({sc['rows']['train']:,} rows after purging {sc['rows']['train_purged']:,}); validation → {sc['validation_end'][:10]} ({sc['rows']['validation']:,}); test → {sc['test_end'][:10]} ({sc['rows']['test']:,}).",
             f"- Model selection rule: {em['selection_rule']}. Selected: **{em['selected_model']}**.", "- Features are point-in-time: computed from transactions strictly before each one (verified by a leakage test and an incremental-vs-brute-force equality test).",
             "- Labels live in separate tables and are never read by inference, graph or risk code (enforced by a test).", "", "## 3. Feature-group comparison (transaction level)",
             "", "| Features / algorithm | Train PR-AUC | Val PR-AUC | Test PR-AUC | Test 95% CI | Test ROC-AUC | P@1% | R@1% | R@2% |", "|---|---|---|---|---|---|---|---|---|"]
        for k, v in r["models"].items():
            ci = v["test"].get("pr_auc_ci95")
            L.append(f"| {k}{' ✓' if k == em['selected_model'] else ''} | {f(v['train']['pr_auc'])} | {f(v['validation']['pr_auc'])} | {f(v['test']['pr_auc'])} | {f(ci[0]) + '–' + f(ci[1]) if ci else '—'} | {f(v['test']['roc_auc'])} | {pc(v['test']['capacity']['0.010']['precision'])} | {pc(v['test']['capacity']['0.010']['recall'])} | {pc(v['test']['capacity']['0.020']['recall'])} |")
        rb, un = r["rules_baseline"]["test"], r["unsupervised"]["test"]
        L += [f"| Rules baseline (no ML) | {f(r['rules_baseline']['train']['pr_auc'])} | {f(r['rules_baseline']['validation']['pr_auc'])} | {f(rb['pr_auc'])} | — | {f(rb['roc_auc'])} | {pc(rb['capacity']['0.010']['precision'])} | {pc(rb['capacity']['0.010']['recall'])} | {pc(rb['capacity']['0.020']['recall'])} |",
              f"| Unsupervised IsolationForest | {f(r['unsupervised']['train']['pr_auc'])} | {f(r['unsupervised']['validation']['pr_auc'])} | {f(un['pr_auc'])} | — | {f(un['roc_auc'])} | {pc(un['capacity']['0.010']['precision'])} | {pc(un['capacity']['0.010']['recall'])} | {pc(un['capacity']['0.020']['recall'])} |", ""]
        mm = r["models"]
        gl = lambda g: mm[f"{g}/lightgbm"]["test"]["pr_auc"]
        L += ["### Do graph features add value?", f"With LightGBM, test PR-AUC is **{f(gl('A_transaction'))}** (transaction only), **{f(gl('B_behavioral'))}** (+ behavioural), **{f(gl('C_graph'))}** (+ graph, no behavioural), **{f(gl('D_combined'))}** (all). "
              "Differences between models whose bootstrap intervals overlap should not be over-interpreted. " + order_sentence(mm), "",
              "### Held-out scenario templates (stronger check)", r.get("holdout_description", ""), "", "| Model | Test PR-AUC (held-out templates) |", "|---|---|"]
        for k, v in r["holdout_templates"].items():
            L.append(f"| {k} | {f(v['pr_auc'])} |")
        th = em["thresholds"]
        L += ["", "## 4. Thresholds, costs and calibration", "", "| Rule | Threshold | Alerts | TP | FP | FN | Precision | Recall | F1 | FPR | FNR |", "|---|---|---|---|---|---|---|---|---|---|---|"]
        for n, k in (("F1-optimal (validation)", "f1_optimal_validation"), ("Cost-optimal (validation, assumed costs)", "cost_optimal_validation"), ("Top 1% capacity", "top_1pct_capacity")):
            t = th[k]
            L.append(f"| {n} | {f(t['threshold'])} | {t['n_alerts']} | {t['tp']} | {t['fp']} | {t['fn']} | {pc(t['precision'])} | {pc(t['recall'])} | {f(t['f1'])} | {pc(t['fpr'], 2)} | {pc(t['fnr'])} |")
        c = em["cost_assumptions"]
        cal = em["calibration"]
        L += ["", f"Cost assumptions (not measured): ₹{c['cost_per_false_positive_inr']:.0f} per false-positive review; {c['loss_rate_on_missed_value']:.0%} of missed suspicious value assumed lost. {c['note']}", "",
              f"Calibration on the test period — raw: Brier {cal['raw']['brier']:.4f}, ECE {cal['raw']['ece']:.4f}; after isotonic calibration fitted on validation: Brier {cal['isotonic_on_validation']['brier']:.4f}, ECE {cal['isotonic_on_validation']['ece']:.4f}. "
              f"{cal['conclusion']}", "", "## 5. Business-impact benchmark (cases, not transactions)", "", f"Evaluation window {bi['evaluation_window']['start'][:10]} → {bi['evaluation_window']['end'][:10]}: **{bi['evaluation_window']['n_suspicious_scenarios_in_window']} simulated suspicious scenarios**, "
              f"{bi['evaluation_window']['n_suspicious_transactions']} suspicious transactions. A *case* is a group of top-scoring transactions of one account within 24h (txn-level approaches) or one AEGIS alert. A case is a true positive if ≥50% of its transactions belong to a suspicious scenario; "
              "a scenario is detected if a true-positive case in the top-N contains one of its transactions.", "",
              "**Read with care:** the case unit is not equally granular across approaches. An AEGIS alert bundles a whole pattern (several accounts and transactions), whereas a transaction-level case is a cluster of one account's top-scoring payments, so AEGIS reaches high scenario recall with few cases but asks the analyst to read more transactions per case (see the *Txns to inspect* column). Precision at N falls once the true cases are exhausted (the window holds only ~19 suspicious scenarios plus benign look-alikes), so P@100 mostly reflects how many true leads exist, not ranking quality.", "", "| Approach | P@25 | Recall@25 | P@50 | Recall@50 | P@100 | Recall@100 | Txns to inspect @25 / @100 | Assumed cost per detected scenario @100 |", "|---|---|---|---|---|---|---|---|---|"]
        for k, v in bi["approaches"].items():
            b = v["by_capacity"]
            L.append(f"| {NAMES.get(k, k)} | {pc(b['25']['precision'], 0)} | {pc(b['25']['scenario_recall'], 0)} | {pc(b['50']['precision'], 0)} | {pc(b['50']['scenario_recall'], 0)} | {pc(b['100']['precision'], 0)} | {pc(b['100']['scenario_recall'], 0)} | {b['25']['transactions_to_inspect']:,} / {b['100']['transactions_to_inspect']:,} | ₹{b['100']['assumed_cost_per_detected_scenario_inr']:,.0f} |")
        a = bi["assumptions"]
        L += ["", f"Assumptions: {a['minutes_per_case']} analyst-minutes per case at ₹{a['analyst_cost_per_hour_inr']}/h → ₹{a['cost_per_case_inr']:.0f}/case. {a['note']} **No savings or prevented losses are claimed.**", ""]
        L += ["Sensitivity of review cost (AEGIS combined risk, 100 cases): " + "; ".join(f"₹{x['cost_per_case_inr']:.0f}/case → ₹{x['review_cost_inr']:,.0f} total, ₹{x['cost_per_detected_scenario_inr']:,.0f} per detected scenario" for x in bi["sensitivity_cost_per_case"]) + ".", ""]
        if "robustness" in bi:
            L += ["## 6. Evasion stress test", bi["robustness"]["description"], "", "| Evasion level | Model PR-AUC | Model recall@1% | Rules PR-AUC | Rules recall@1% |", "|---|---|---|---|---|"]
            for x in bi["robustness"]["rows"]:
                L.append(f"| {x['evasion_level']} | {f(x['model_pr_auc'])} | {pc(x['model_recall_at_1pct'])} | {f(x['rules_pr_auc'])} | {pc(x['rules_recall_at_1pct'])} |")
            L += ["", "Interpretation: the model degrades only slightly because simulated suspicious payments remain large and unusual in amount even when hops are slowed and value is leaked. Real adversaries would also adapt amounts; this test is a robustness probe, not a guarantee.", ""]
        L += ["## 7. Limitations", ""] + [f"- {x}" for x in em["limitations"] + bi["limitations"]]
        (DOCS / "evaluation_report.md").write_text("\n".join(L) + "\n", encoding="utf-8")
        print("wrote", DOCS / "evaluation_report.md")

        top = [f"- `{k}` — {v:.3f}" for k, v in list(em.get("feature_importance", {}).items())[:8]]
        M = ["# Model card — AEGIS transaction risk model", "", f"- **Run / version:** `{run.model_run_id}` / `{run.model_version}`  · feature version `{run.feature_version}` · risk-config `risk-v1`",
             f"- **Model:** {em['selected_model']} (LightGBM gradient-boosted trees) wrapped with an isotonic calibrator fitted on the validation period, plus an unsupervised IsolationForest anomaly signal (no labels).",
             f"- **Trained on:** synthetic dataset `{run.dataset_id}` (version `{run.dataset_version}`), {sc['train_start'][:10]} → {sc['train_end'][:10]}; validation to {sc['validation_end'][:10]}; tested {sc['validation_end'][:10]} → {sc['test_end'][:10]}.",
             "- **Intended use:** research and investigation-support prototype that ranks transactions and patterns for analyst review. **Not** a certified AML system, not a basis for automated adverse action, and makes no legal determinations.",
             "- **Out of scope:** real customer decisions, regulatory filings, any use on real data without independent validation, fairness assessment and a security review.", "",
             "## Output semantics", "The model emits a *risk score* in [0,1]. After isotonic calibration it is monotone with the raw score and better calibrated **on synthetic prevalence only**; it is not a probability of crime. Risk bands (Critical ≥0.80, High ≥0.60, Medium ≥0.40, Low ≥0.20) are operational categories.", "",
             "## Inputs", f"{len(ALL_COLS)} point-in-time features in three groups: transaction (amount, time, type, channel, near-reference-amount), account behaviour (windowed counts/values, velocity, dormancy, z-scores, new-counterparty) and local graph (destination fan-in, reciprocity, 2/3-hop cycle closure, pass-through chain position, forwarding ratio). See `docs/data_dictionary.md`.", "",
             "## Measured performance (test period, synthetic labels)", f"- PR-AUC {f(r['models'][em['selected_model']]['test']['pr_auc'])} (prevalence {pc(sc['positives']['test'] / sc['rows']['test'], 2)}); recall at 1% review capacity {pc(r['models'][em['selected_model']]['test']['capacity']['0.010']['recall'])}; rules baseline PR-AUC {f(rb['pr_auc'])}.",
             "- Full tables with bootstrap intervals, held-out template results, thresholds and calibration: [`evaluation_report.md`](evaluation_report.md).", "", "## Top features (normalised split gain)", *top, "",
             "## Explainability", "Per-alert SHAP (TreeExplainer) contributions for the highest-scoring transaction are stored with each alert. Attributions describe model behaviour; they are not proof of causality or intent.", "",
             "## Known limitations and risks", *[f"- {x}" for x in em["limitations"]],
             "- Amount alone separates many simulated scenarios (the transaction-only model is a strong baseline) — an artefact of synthetic amount distributions.",
             "- Account-age and counterparty-novelty features may act as proxies for synthetic generation choices (e.g. ~35% of scenario participants are recently opened accounts).",
             "- No fairness or subgroup analysis has been performed; synthetic customer segments carry no demographic meaning.", "- Drift monitoring is distributional (PSI); it cannot detect accuracy loss without labels. Promotion of a new model is manual.", ""]
        (DOCS / "model_card.md").write_text("\n".join(M), encoding="utf-8")
        print("wrote", DOCS / "model_card.md")


from app.features.engine import ALL_FEATURES as ALL_COLS

if __name__ == "__main__":
    main()
